// src/components/SvgFlow.js
import React, { useRef, useEffect } from "react";
import * as d3 from "d3";

function parseCodeToFlowchart(code = "") {
  const nodes = [];
  const edges = [];

  if (!code || !code.trim()) return { nodes, edges };

  // Parse function declaration
  const fnMatch = code.match(/function\s+(\w+)\s*\(([^)]*)\)/) || code.match(/const\s+(\w+)\s*=\s*\(([^)]*)\)\s*=>/);
  const fnName = fnMatch ? fnMatch[1] : "fn";
  const param = fnMatch ? fnMatch[2].trim() : "";

  // Start node
  nodes.push({ 
    id: "start", 
    label: "Start", 
    type: "terminal",
    shape: "stadium" 
  });

  // Function declaration node
  nodes.push({
    id: "function",
    label: `Function: ${fnName}(${param})`,
    type: "process",
    shape: "rectangle"
  });
  edges.push({ from: "start", to: "function" });

  // Input parameter node
  if (param) {
    nodes.push({ 
      id: "input", 
      label: `Input parameter: ${param}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ from: "function", to: "input" });
  }

  // Decision node for if condition
  const hasCondition = /if\s*\(/.test(code);
  if (hasCondition) {
    const condMatch = code.match(/if\s*\(([^)]+)\)/);
    const condition = condMatch ? condMatch[1].trim() : "condition";
    
    nodes.push({ 
      id: "decision", 
      label: `Check if ${condition}`, 
      type: "decision",
      shape: "diamond" 
    });
    edges.push({ 
      from: param ? "input" : "function", 
      to: "decision" 
    });

    // True path
    const trueLogMatch = code.match(/if\s*\([^{]*\)\s*{([^}]*)}/);
    const trueLog = trueLogMatch ? 
      trueLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "true branch";
    
    nodes.push({ 
      id: "true_process", 
      label: `Print: ${trueLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "true_process", 
      label: "Yes" 
    });

    // False path
    const falseLogMatch = code.match(/else\s*{([^}]*)}/);
    const falseLog = falseLogMatch ? 
      falseLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "false branch";

    nodes.push({ 
      id: "false_process", 
      label: `Print: ${falseLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "false_process", 
      label: "No" 
    });

    // Connect both paths to end
    edges.push({ from: "true_process", to: "end" });
    edges.push({ from: "false_process", to: "end" });
  } else {
    // If no condition, connect directly to end
    edges.push({ from: param ? "input" : "function", to: "end" });
  }

  // End node
  nodes.push({ 
    id: "end", 
    label: "End", 
    type: "terminal",
    shape: "stadium" 
  });

  return { nodes, edges };
}

function SvgFlow({ graph, code }) {
  const svgRef = useRef();

  useEffect(() => {
    const g = graph && graph.nodes && graph.nodes.length ? graph : parseCodeToFlowchart(code);
    const svgEl = d3.select(svgRef.current);
    svgEl.selectAll("*").remove(); // clear old diagram

    if (!g.nodes || !g.nodes.length) {
      // show placeholder text
      svgEl
        .append("text")
        .attr("x", 20)
        .attr("y", 30)
        .attr("fill", "#6b7280")
        .style("font-size", "14px")
        .text('No flowchart yet — click "Generate Flowchart"');
      return;
    }

    const width = Math.max(800, svgRef.current.parentElement?.clientWidth || 900);
    const nodeWidth = 220;
    const nodeHeight = 60;
    const verticalGap = 90;

    svgEl.attr("width", "100%").attr("height", g.nodes.length * verticalGap + 100);

    // simple top-to-bottom layout: center all nodes horizontally
    g.nodes.forEach((n, i) => {
      n.x = width / 2;
      n.y = 40 + i * verticalGap;
    });

    // markers for arrows
    svgEl
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 6)
      .attr("markerHeight", 6)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "#374151");

    // draw edges
    const edgeGroup = svgEl.append("g").attr("class", "edges");
    g.edges.forEach((e) => {
      const from = g.nodes.find((n) => n.id === e.from);
      const to = g.nodes.find((n) => n.id === e.to);
      if (!from || !to) return;

      // straight vertical/curved path
      const startX = from.x;
      const startY = from.y + nodeHeight / 2;
      const endX = to.x;
      const endY = to.y - nodeHeight / 2;

      const path = `M ${startX} ${startY} C ${startX} ${(startY + endY) / 2} ${endX} ${(startY + endY) / 2} ${endX} ${endY}`;

      edgeGroup
        .append("path")
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", "#374151")
        .attr("stroke-width", 2)
        .attr("marker-end", "url(#arrow)");

      if (e.label) {
        // label mid-point
        edgeGroup
          .append("text")
          .attr("x", (startX + endX) / 2 + 10)
          .attr("y", (startY + endY) / 2 - 6)
          .attr("fill", "#374151")
          .style("font-size", "12px")
          .text(e.label);
      }
    });

    // draw nodes
    const nodeGroup = svgEl.append("g").attr("class", "nodes");
    const gNodes = nodeGroup.selectAll(".node").data(g.nodes).enter().append("g").attr("class", "node");

    // shapes
    gNodes.each(function (d) {
      const node = d3.select(this);
      const x = d.x - nodeWidth / 2;
      const y = d.y - nodeHeight / 2;

      if (d.type === "decision" || d.type === "condition") {
        // diamond centered at (d.x, d.y)
        const cx = d.x;
        const cy = d.y;
        const w = nodeWidth / 2;
        const h = nodeHeight / 2;
        const points = [
          [cx, cy - h],
          [cx + w, cy],
          [cx, cy + h],
          [cx - w, cy],
        ]
          .map((p) => p.join(","))
          .join(" ");
        node
          .append("polygon")
          .attr("points", points)
          .attr("fill", "#dbeafe")
          .attr("stroke", "#2563eb")
          .attr("stroke-width", 2);
        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "12px")
          .style("font-weight", "500")
          .text(d.label);
      } else if (d.shape === "stadium") {
        // Terminal shape (oval)
        node
          .append("ellipse")
          .attr("cx", d.x)
          .attr("cy", d.y)
          .attr("rx", nodeWidth / 2)
          .attr("ry", nodeHeight / 2)
          .attr("fill", "#dcfce7")
          .attr("stroke", "#16a34a")
          .attr("stroke-width", 2);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "13px")
          .style("font-weight", "600")
          .text(d.label);
      } else if (d.shape === "parallelogram") {
        // Parallelogram for input/output
        const skewX = 20;
        node
          .append("polygon")
          .attr("points", [
            [x + skewX, y],
            [x + nodeWidth, y],
            [x + nodeWidth - skewX, y + nodeHeight],
            [x, y + nodeHeight],
          ]
            .map((p) => p.join(","))
            .join(" "))
          .attr("fill", "#fff9db")
          .attr("stroke", "#f59e0b")
          .attr("stroke-width", 2);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "12px")
          .style("font-weight", "500")
          .text(d.label);
      } else {
        // Rectangle for process
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 8)
          .attr("fill", "#f3f4f6")
          .attr("stroke", "#6b7280")
          .attr("stroke-width", 2);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "12px")
          .style("font-weight", "500")
          .text(d.label);
      }
    });
  }, [graph, code]);

  return (
    <div style={{ background: "#fff", padding: "18px", borderRadius: "12px", boxShadow: "0 2px 6px rgba(0,0,0,0.06)" }}>
      <svg ref={svgRef} style={{ width: "100%", height: "100%" }}></svg>
    </div>
  );
}

export default SvgFlow;
